from produire import produire,paras,table,steps
from medicaments import valaciclovir
parts=[
('Le zona otique avec paralysie faciale correspond au syndrome de Ramsay-Hunt. Les {éléments du syndrome} peuvent apparaître à des moments différents.',paras('Il associe classiquement douleur auriculaire, éruption vésiculeuse de la région auriculaire et paralysie faciale périphérique. Une atteinte auditive ou vestibulaire peut s’y ajouter ; l’absence initiale de vésicules n’exclut pas une cause zostérienne.')),
('La réactivation du virus varicelle-zona est favorisée par certains terrains. Les {facteurs de contexte} comprennent âge et immunodépression.',paras('Une douleur sévère peut précéder les lésions visibles. La présentation et le risque de complication justifient une évaluation précoce plutôt qu’une attente de la triade complète.')),
('La réactivation virale provoque une atteinte nerveuse inflammatoire. Les {conséquences fonctionnelles} concernent visage, cornée, audition et équilibre.',paras('La faiblesse des muscles faciaux peut empêcher la fermeture de l’œil et exposer la cornée. Une extension cochléovestibulaire peut provoquer hypoacousie, acouphènes et vertiges.')),
('Toute paralysie faciale aiguë nécessite un examen neurologique et otologique. Les {signes urgents} déterminent la filière.',paras('Déficits neurologiques associés ou suspicion d’AVC imposent la filière d’urgence correspondante. Douleur oculaire, rougeur, baisse visuelle, œil non protégé, surdité brusque, vertige important ou immunodépression nécessitent une évaluation urgente.')),
('L’entretien précise début de douleur, éruption et faiblesse faciale. Les {questions ciblées} recherchent complications et diagnostics alternatifs.',paras('Demander troubles du goût, hyperacousie, baisse auditive, vertige et fermeture palpébrale. Rechercher symptômes neurologiques, exposition à des tiques, immunodépression et antécédents otologiques ; le diagnostic de paralysie idiopathique ne doit pas être posé sans examen de l’oreille.')),
('Examiner toute la motricité faciale et la fermeture oculaire. Les {sites de recherche des lésions} incluent pavillon, conque et conduit.',paras('Décrire front, joue et bouche, puis rechercher vésicules ou croûtes auriculaires et lésions buccales selon contexte. Vérifier tympan, audition et autres nerfs crâniens ; le seul respect ou non du front ne suffit pas à écarter toutes les causes centrales.')),
('Le {diagnostic différentiel} dépasse la paralysie de Bell. Une douleur auriculaire sévère doit faire chercher une cause secondaire.',table(['Contexte','Alternative'],[['Déficits neurologiques associés.','Cause centrale, notamment AVC.'],['Inflammation otologique ou mastoïdienne.','Complication d’otite ou autre lésion.'],['Atteinte bilatérale ou exposition compatible.','Infection ou maladie systémique, dont borréliose selon contexte.'],['Évolution progressive ou masse.','Cause tumorale.'],['Aucune cause retrouvée après évaluation.','Paralysie faciale idiopathique.']])) ,
('Le diagnostic est souvent clinique devant l’association caractéristique. Les {limites de la triade} justifient une surveillance de l’évolution.',paras('Une réactivation sans éruption initiale peut être difficile à distinguer d’autres paralysies. La gradation du déficit, l’examen de la cornée et la recherche d’une atteinte auditive guident la prise en charge même avant confirmation complète.')),
('Le bilan dépend de la présentation et de la gravité. Les {examens complémentaires} ne doivent pas retarder les soins indispensables.',paras('Audiométrie si plainte auditive, examen ophtalmologique si risque cornéen ou symptôme, prélèvement virologique selon doute et conséquences. Imagerie et explorations neurologiques sont indiquées dans les formes atypiques ou selon les diagnostics alternatifs.')),
('L’{arbre de prise en charge} associe protection de l’œil et traitement précoce. La gravité et le terrain déterminent ambulatoire ou hospitalisation.',steps('Écarter une urgence neurologique et examiner l’œil, l’audition et l’équilibre.', 'Mettre en place une protection cornéenne appropriée si fermeture incomplète et organiser le suivi spécialisé.', 'Décider antiviral et éventuelle corticothérapie avec vérification des contre-indications et de la fonction rénale.', 'Suivre récupération faciale, audition et douleur ; réévaluer toute aggravation ou évolution atypique.')),
('Le protocole HUG prévoit un antiviral systématique pour Ramsay-Hunt. Les {repères suisses et leurs limites} doivent être distingués selon le médicament.',paras('La protection cornéenne comprend lubrification et protection mécanique adaptées à la fermeture, avec avis ophtalmologique selon les signes. Le choix des préparations et modalités doit être individualisé.', '@@MEDICAMENTS@@')),
('Le {suivi fonctionnel} recherche récupération et séquelles. Les précautions de contact protègent les personnes susceptibles de varicelle.',paras('Éviter le contact direct avec les vésicules, respecter hygiène des mains et conseils vis-à-vis des personnes non immunisées vulnérables. Poursuivre les soins oculaires et organiser rééducation ou prise en charge spécialisée si faiblesse, synkinésies ou douleur persistent.')),
('Les signes de Ramsay-Hunt ne sont pas toujours simultanés. La cornée doit être protégée si l’œil ferme mal. Antiviral précoce et adaptation rénale sont essentiels. Une présentation atypique nécessite de revoir le diagnostic.','')]
quiz=[('Quelle association classique définit Ramsay-Hunt ?','Otalgie, vésicules auriculaires et paralysie faciale périphérique.'),('Les trois signes sont-ils toujours simultanés ?','Non.'),('L’absence initiale de vésicules exclut-elle le zona ?','Non.'),('Pourquoi l’œil est-il à risque ?','La fermeture incomplète expose la cornée.'),('Une baisse visuelle peut-elle attendre le suivi ordinaire ?','Non : avis urgent.'),('Quels symptômes évoquent une atteinte cochléovestibulaire ?','Baisse auditive, acouphènes et vertige.'),('Faut-il examiner l’oreille devant une paralysie faciale ?','Oui.'),('Un déficit neurologique associé change-t-il la filière ?','Oui : rechercher notamment un AVC.'),('Quel schéma adulte de Valtrex est cité pour le zona ?','1 000 mg trois fois par jour pendant sept jours, à adapter aux reins.'),('La dose est-elle identique si clairance à 20 ml/min ?','Non : la notice du zona prévoit 1 000 mg une fois par jour pour 10–29 ml/min.'),('La notice recommande-t-elle Valtrex chez l’enfant ?','Non, faute de données dans cette information.'),('La dose générale de prednisone constitue-t-elle un schéma AIPS spécifique de Ramsay-Hunt ?','Non : cette indication et son schéma ne figurent pas nominativement dans la notice lue.'),('Une présentation après 72 heures doit-elle être abandonnée ?','Non : elle demande une décision spécialisée selon complications et évolution.'),('La corticothérapie remplace-t-elle l’antiviral ou les soins de l’œil ?','Non.')]
produire(6,parts,quiz,(4,8,18,19,25),valaciclovir)
